# Build the animation tree project programmatically
@tool
extends EditorScript

func _run():
	_build_animations()
	_build_scene()
	print("Done")

func _build_animations():
	# Create an AnimationLibrary
	var library = AnimationLibrary.new()
	var anims = [
		"idle", "walk_north", "walk_south", "walk_east", "walk_west", "attack"
	]
	for name in anims:
		var anim = Animation.new()
		anim.length = 1.0
		var track = anim.add_track(Animation.TYPE_VALUE)
		anim.track_set_path(track, NodePath("Sprite2D:modulate"))
		anim.track_insert_key(track, 0.0, Color.WHITE)
		library.add_animation(name, anim)

	# Save the library? For this we'll embed.
	pass

func _build_scene():
	var scene = PackedScene.new()
	var root = Node2D.new()
	root.name = "Player"

	# AnimationPlayer
	var ap = AnimationPlayer.new()
	ap.name = "AnimationPlayer"
	root.add_child(ap)
	ap.owner = root

	var library = AnimationLibrary.new()
	var anims = [
		"idle", "walk_north", "walk_south", "walk_east", "walk_west", "attack"
	]
	for name in anims:
		var anim = Animation.new()
		anim.length = 1.0
		var track = anim.add_track(Animation.TYPE_VALUE)
		anim.track_set_path(track, NodePath("Sprite2D:modulate"))
		anim.track_insert_key(track, 0.0, Color.WHITE)
		library.add_animation(name, anim)
	ap.add_animation_library("", library)

	var sprite = Sprite2D.new()
	sprite.name = "Sprite2D"
	root.add_child(sprite)
	sprite.owner = root

	# AnimationTree
	var tree = AnimationTree.new()
	tree.name = "AnimationTree"
	root.add_child(tree)
	tree.owner = root
	tree.anim_player = ap.get_path()

	var sm = AnimationNodeStateMachine.new()
	tree.tree_root = sm

	# Locomotion BlendSpace2D
	var locomotion = AnimationNodeBlendSpace2D.new()
	locomotion.add_blend_point(AnimationNodeAnimation.new_animation("idle"), Vector2(0, 0))
	locomotion.add_blend_point(AnimationNodeAnimation.new_animation("walk_north"), Vector2(0, -1))
	locomotion.add_blend_point(AnimationNodeAnimation.new_animation("walk_south"), Vector2(0, 1))
	locomotion.add_blend_point(AnimationNodeAnimation.new_animation("walk_east"), Vector2(1, 0))
	locomotion.add_blend_point(AnimationNodeAnimation.new_animation("walk_west"), Vector2(-1, 0))
	sm.add_node("Locomotion", locomotion)

	# Attack
	var attack = AnimationNodeAnimation.new()
	attack.animation = &"attack"
	sm.add_node("Attack", attack)

	# Transitions
	sm.add_transition("Locomotion", "Attack", "Locomotion -> Attack")
	var trans1 = sm.get_transition(sm.find_transition("Locomotion", "Attack"))
	trans1.switch_mode = AnimationNodeStateMachineTransition.SWITCH_MODE_AT_END
	trans1.advance_mode = AnimationNodeStateMachineTransition.ADVANCE_MODE_ENABLED
	trans1.advance_condition = &"condition_attack"

	sm.add_transition("Attack", "Locomotion", "Attack -> Locomotion")
	var trans2 = sm.get_transition(sm.find_transition("Attack", "Locomotion"))
	trans2.switch_mode = AnimationNodeStateMachineTransition.SWITCH_MODE_AT_END
	trans2.advance_mode = AnimationNodeStateMachineTransition.ADVANCE_MODE_AUTO

	# PlayerAnimController
	var controller = Node.new()
	controller.name = "PlayerAnimController"
	root.add_child(controller)
	controller.owner = root
	var script = load("res://scripts/PlayerAnimController.gd")
	controller.set_script(script)

	scene.pack(root)
	ResourceSaver.save(scene, "res://scenes/Player.tscn")

	root.free()
EOF
